/// Dispatches one IRP through the unified async-capable receive boundary.
fn dispatch(device: PDEVICE_OBJECT, irp: PIRP, major: DispatchMajor) -> NTSTATUS {
    let received = match ReceivedIrp::decode(device, irp) {
        Ok(received) => received,
        Err(error) => return ReceivedIrp::complete_decode_error(irp, error),
    };

    match dispatch_policy(major) {
        DispatchPolicy::Immediate => received.complete_result(execute_immediate(major)),
        DispatchPolicy::Queued => CompletionReactor::receive(received, major),
        DispatchPolicy::FsRtlFileLock => dispatch_file_lock(received),
    }
}

/// Queue policy for a received major function.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum DispatchPolicy {
    /// Complete during the dispatch callback.
    Immediate,
    /// Mark pending and execute on the dedicated device actor.
    Queued,
    /// Transfer terminal completion to the FsRtl byte-range lock package.
    FsRtlFileLock,
}

/// Returns the queue policy for a major function.
const fn dispatch_policy(major: DispatchMajor) -> DispatchPolicy {
    match major {
        DispatchMajor::DeviceControl => DispatchPolicy::Immediate,
        DispatchMajor::LockControl => DispatchPolicy::FsRtlFileLock,
        DispatchMajor::Create
        | DispatchMajor::Cleanup
        | DispatchMajor::Close
        | DispatchMajor::Read
        | DispatchMajor::Write
        | DispatchMajor::QueryInformation
        | DispatchMajor::SetInformation
        | DispatchMajor::QueryVolumeInformation
        | DispatchMajor::SetVolumeInformation
        | DispatchMajor::DirectoryControl
        | DispatchMajor::FileSystemControl
        | DispatchMajor::FlushBuffers
        | DispatchMajor::QueryEa
        | DispatchMajor::SetEa
        | DispatchMajor::QuerySecurity
        | DispatchMajor::SetSecurity
        | DispatchMajor::Shutdown => DispatchPolicy::Queued,
    }
}

/// Decodes a lock target, then lets FsRtl own and complete the lock-control IRP.
fn dispatch_file_lock(mut received: ReceivedIrp) -> NTSTATUS {
    match received.with_active(crate::request::file_info::lock_control) {
        Ok(file_control_block) => received.delegate_byte_range_lock(file_control_block),
        Err(error) => received.complete_result(Err(error)),
    }
}

/// Executes and terminally completes or delegates one legacy request body during migration.
#[cfg_attr(
    test,
    expect(
        dead_code,
        reason = "kernel device actor is compiled out in unit tests"
    )
)]
pub(crate) async fn execute_owned(mut owned: OwnedIrp) {
    if actor_request_requires_handle_authorization(&owned)
        && let Err(error) = authorize_actor_request(&mut owned)
    {
        owned.complete_result(Err(error));
        return;
    }
    let _status = match owned.actor_request() {
        ActorRequest::Cleanup => {
            let result = crate::request::file_info::cleanup(owned.request()).await;
            owned.complete_result(result)
        }
        ActorRequest::Close => {
            let result = owned
                .request()
                .with_active(crate::request::file_info::close);
            owned.complete_result(result)
        }
        ActorRequest::Captured(prepared) => match prepared {
            PreparedRequest::Create => {
                let result = crate::request::create::execute(owned.request()).await;
                owned.complete_create_result(result)
            }
            PreparedRequest::FileSystemControl(minor) => {
                let minor = *minor;
                let result =
                    crate::request::file_system_control::execute(owned.request(), minor).await;
                owned.complete_result(result)
            }
            PreparedRequest::DirectoryControl(request) => match request {
                PreparedDirectoryControl::QueryDirectory(_) => {
                    let result = crate::request::file_info::query_directory(owned.request()).await;
                    owned.complete_result(result)
                }
                PreparedDirectoryControl::NotifyChangeDirectory => {
                    crate::request::file_info::notify_change_directory(owned)
                }
            },
            PreparedRequest::QuerySecurity { .. } => {
                let result = crate::request::security::query(owned.request()).await;
                owned.complete_result(result)
            }
            PreparedRequest::SetSecurity { .. } => {
                let result = crate::request::security::set(owned.request()).await;
                owned.complete_result(result)
            }
            PreparedRequest::Read(_) => {
                let result = crate::request::file_info::read(owned.request()).await;
                owned.complete_result(result)
            }
            PreparedRequest::Write(_) => {
                let result = crate::request::file_info::write(owned.request()).await;
                owned.complete_result(result)
            }
            PreparedRequest::QueryInformation => {
                let result = crate::request::file_info::query(owned.request()).await;
                owned.complete_result(result)
            }
            PreparedRequest::SetInformation => {
                let result = crate::request::file_info::set(owned.request()).await;
                owned.complete_result(result)
            }
            PreparedRequest::QueryVolumeInformation => {
                let result = crate::request::volume_info::query(owned.request()).await;
                owned.complete_result(result)
            }
            PreparedRequest::SetVolumeInformation => {
                let result = crate::request::volume_info::set(owned.request()).await;
                owned.complete_result(result)
            }
            PreparedRequest::FlushBuffers => {
                let result = crate::request::file_info::flush(owned.request()).await;
                owned.complete_result(result)
            }
            PreparedRequest::QueryEa(_) => {
                let result = crate::request::ea::query(owned.request()).await;
                owned.complete_result(result)
            }
            PreparedRequest::SetEa => {
                let result = crate::request::ea::set(owned.request()).await;
                owned.complete_result(result)
            }
            PreparedRequest::Shutdown => {
                let result = crate::request::file_info::shutdown(owned.request()).await;
                owned.complete_result(result)
            }
        },
    };
}

/// Selects actor requests that operate through an already-opened FILE_OBJECT.
fn actor_request_requires_handle_authorization(owned: &OwnedIrp) -> bool {
    match owned.actor_request() {
        ActorRequest::Cleanup | ActorRequest::Close => false,
        ActorRequest::Captured(
            PreparedRequest::Create
            | PreparedRequest::FileSystemControl(_)
            | PreparedRequest::Shutdown,
        ) => false,
        ActorRequest::Captured(
            PreparedRequest::DirectoryControl(_)
            | PreparedRequest::QuerySecurity { .. }
            | PreparedRequest::SetSecurity { .. }
            | PreparedRequest::Read(_)
            | PreparedRequest::Write(_)
            | PreparedRequest::QueryInformation
            | PreparedRequest::SetInformation
            | PreparedRequest::QueryVolumeInformation
            | PreparedRequest::SetVolumeInformation
            | PreparedRequest::FlushBuffers
            | PreparedRequest::QueryEa(_)
            | PreparedRequest::SetEa,
        ) => true,
    }
}

/// Applies mounted-volume lifecycle policy before an ordinary opened-handle request.
/// # Errors
///
/// Returns an error when the FILE_OBJECT is invalid, locked by another handle, or dismounted.
fn authorize_actor_request(owned: &mut OwnedIrp) -> DriverResult<()> {
    owned.request().with_active(|active| {
        let device = active.device();
        let opened = OpenedFileObject::decode(active.current_stack()?.file_object()?)?;
        let (volume, file_object) = match opened {
            OpenedFileObject::Node(opened) => (opened.volume(), opened.file_object()),
            OpenedFileObject::Volume(opened) => (opened.volume(), opened.file_object()),
        };
        if MountedVolumeDevice::vcb(device) != Some(volume) {
            crate::kernel::fatal::KernelWideInconsistency::file_object_context_corruption()
                .bugcheck();
        }
        let operations = unsafe {
            // SAFETY: The request runs on the mounted-device actor. This synchronous authorization
            // observes the actor-owned control plane before the handler claims the operation lane.
            VolumeControlBlock::claim_operation_lane(volume)
        };
        operations.authorize_handle(file_object)
    })
}

/// Executes an immediate IRP during the dispatch callback.
/// # Errors
///
/// Returns an error when an immediate request cannot be decoded or is not valid for immediate
/// execution.
fn execute_immediate(major: DispatchMajor) -> DriverResult<IrpCompletion> {
    match major {
        DispatchMajor::DeviceControl => crate::request::file_system_control::device_control(),
        DispatchMajor::Create
        | DispatchMajor::Close
        | DispatchMajor::Cleanup
        | DispatchMajor::Read
        | DispatchMajor::Write
        | DispatchMajor::QueryInformation
        | DispatchMajor::SetInformation
        | DispatchMajor::QueryVolumeInformation
        | DispatchMajor::SetVolumeInformation
        | DispatchMajor::DirectoryControl
        | DispatchMajor::FileSystemControl
        | DispatchMajor::FlushBuffers
        | DispatchMajor::QueryEa
        | DispatchMajor::SetEa
        | DispatchMajor::LockControl
        | DispatchMajor::QuerySecurity
        | DispatchMajor::SetSecurity
        | DispatchMajor::Shutdown => Err(DriverError::InvalidDeviceRequest),
    }
}

#[cfg(test)]
mod tests {
    use crate::irp::DispatchMajor;

    use super::{DispatchPolicy, dispatch_policy};

    /// # Panics
    ///
    /// Panics when the shutdown request stops using the passive-level queue.
    #[test]
    fn shutdown_is_queued_for_passive_level_flush() {
        assert_eq!(
            dispatch_policy(DispatchMajor::Shutdown),
            DispatchPolicy::Queued
        );
    }

    /// # Panics
    ///
    /// Panics when lock-control IRPs stop being completed by FsRtl.
    #[test]
    fn lock_control_is_delegated_to_fsrtl() {
        assert_eq!(
            dispatch_policy(DispatchMajor::LockControl),
            DispatchPolicy::FsRtlFileLock
        );
    }

    /// # Panics
    ///
    /// Panics when cleanup stops using the actor barrier after cancelling earlier pending IRPs.
    #[test]
    fn cleanup_runs_on_actor_after_pending_irps_are_cancelled() {
        assert_eq!(
            dispatch_policy(DispatchMajor::Cleanup),
            DispatchPolicy::Queued
        );
    }

    /// # Panics
    ///
    /// Panics when close stops following create and cleanup on the same actor.
    #[test]
    fn close_runs_after_prior_file_object_operations() {
        assert_eq!(
            dispatch_policy(DispatchMajor::Close),
            DispatchPolicy::Queued
        );
    }
}
